// Builds supabase/seed.sql from src/data/catalogue.json.
// Usage: node scripts/generate-seed.mjs
import { readFileSync, writeFileSync } from "node:fs";

const data = JSON.parse(readFileSync(new URL("../src/data/catalogue.json", import.meta.url)));
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const out = [
  "-- Starting categories, styles and collections for Ansh Arte.",
  "-- Generated by scripts/generate-seed.mjs. Safe to run more than once.",
  "",
];

const collectionSql = (c, catSlug, parentSlug, i) => {
  const cat = parentSlug
    ? `(select s.id from categories s join categories p on s.parent_id = p.id where p.slug = ${q(parentSlug)} and s.slug = ${q(catSlug)})`
    : `(select id from categories where parent_id is null and slug = ${q(catSlug)})`;
  return `insert into collections (category_id, name, slug, tagline, sort) values (${cat}, ${q(c.name)}, ${q(c.slug)}, ${q(c.tagline)}, ${i}) on conflict (slug) do nothing;`;
};

data.categories.forEach((cat, ci) => {
  out.push(
    `insert into categories (name, slug, description, sort) select ${q(cat.name)}, ${q(cat.slug)}, ${q(cat.description)}, ${ci} where not exists (select 1 from categories where parent_id is null and slug = ${q(cat.slug)});`,
  );
  cat.styles.forEach((st, si) => {
    out.push(
      `insert into categories (parent_id, name, slug, description, sort) select (select id from categories where parent_id is null and slug = ${q(cat.slug)}), ${q(st.name)}, ${q(st.slug)}, ${q(st.description)}, ${si} on conflict (parent_id, slug) do nothing;`,
    );
    st.collections.forEach((c, i) => out.push(collectionSql(c, st.slug, cat.slug, i)));
  });
  (cat.collections ?? []).forEach((c, i) => out.push(collectionSql(c, cat.slug, null, i)));
  out.push("");
});

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), out.join("\n"));
console.log("Wrote supabase/seed.sql");
